import { Component } from '@angular/core';

@Component({
  selector: 'app-user-profile',
  template: '<p>User Profile Component</p>'
})
export class UserProfileComponent {
  // Component logic here
}

function withAuth(WrappedComponent: any) {
  @Component({
    selector: 'app-auth-wrapper',
    template: '<ng-container *ngIf="isAuthenticated">
                <ng-container *ngTemplateOutlet="wrappedTemplate"></ng-container>
              </ng-container>',
    providers: []
  })
  class AuthWrapper {
    @Input() userId: string = '';
    isAuthenticated: boolean = false;
    wrappedTemplate: any;

    constructor(private authService: any) {
      this.isAuthenticated = this.authService.checkAuth();
      this.wrappedTemplate = WrappedComponent.__annotations__[0];
    }
  }
  return AuthWrapper;
}

const WrappedUserProfile = withAuth(UserProfileComponent);

@Component({
  selector: 'app-root',
  template: `
    <h1>Authentication Demo</h1>
